BEGIN;

-- 1. 医疗新技术新项目
CREATE TABLE IF NOT EXISTS "医疗新技术新项目" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "项目名称" varchar(200) NOT NULL,
    "申报类别" varchar(50) NOT NULL DEFAULT '临床新技术',
    "技术难度等级" varchar(20) NOT NULL DEFAULT '三级',
    "风险等级" varchar(20) NOT NULL DEFAULT '中风险',
    "负责人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "科室编号" integer REFERENCES "部门"("编号"),
    "团队成员" jsonb NOT NULL DEFAULT '[]'::jsonb,
    "申报年度" integer NOT NULL DEFAULT EXTRACT(YEAR FROM CURRENT_DATE)::integer,
    "计划开始日期" date NOT NULL,
    "计划完成日期" date NOT NULL,
    "预期应用例数" integer NOT NULL DEFAULT 20,
    "技术适应症" text,
    "禁忌症及防范预案" text,
    "准入审批状态" varchar(20) NOT NULL DEFAULT '草稿',
    "伦理审查编号" varchar(100),
    "伦理审查状态" varchar(20) DEFAULT '未关联',
    "医务处审核状态" varchar(20) DEFAULT '待审核',
    "医务处意见" text,
    "医务处审核人编号" integer REFERENCES "人员"("编号"),
    "医务处审核时间" timestamp without time zone,
    "科教处审核状态" varchar(20) DEFAULT '待审核',
    "科教处意见" text,
    "科教处审核人编号" integer REFERENCES "人员"("编号"),
    "科教处审核时间" timestamp without time zone,
    "附件路径" text,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "ix_新技术_状态科室" ON "医疗新技术新项目" ("准入审批状态", "科室编号", "申报年度");

-- 2. 医疗新技术临床应用随访
CREATE TABLE IF NOT EXISTS "医疗新技术临床应用随访" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "新技术编号" bigint NOT NULL REFERENCES "医疗新技术新项目"("编号") ON DELETE CASCADE,
    "患者姓名脱敏" varchar(50) NOT NULL,
    "病历号" varchar(50) NOT NULL,
    "应用日期" date NOT NULL,
    "主要术者编号" integer REFERENCES "人员"("编号"),
    "主要术者姓名" varchar(50),
    "临床疗效" varchar(20) NOT NULL DEFAULT '有效',
    "是否发生不良反应" boolean NOT NULL DEFAULT false,
    "不良反应分级" varchar(20) DEFAULT '无',
    "不良反应描述及处置" text,
    "随访日期" date,
    "记录人编号" integer REFERENCES "人员"("编号"),
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "ix_新技术随访_项目" ON "医疗新技术临床应用随访" ("新技术编号", "应用日期" DESC);

-- 3. 医疗新技术转常规与评奖
CREATE TABLE IF NOT EXISTS "医疗新技术转常规与评奖" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "新技术编号" bigint NOT NULL REFERENCES "医疗新技术新项目"("编号") ON DELETE CASCADE,
    "申请类型" varchar(20) NOT NULL DEFAULT '期满转常规',
    "拟申报奖项" varchar(50),
    "总结报告路径" text,
    "累计开展例数" integer NOT NULL DEFAULT 0,
    "显效率" numeric(5,2),
    "并发症发生率" numeric(5,2),
    "学术产出说明" text,
    "审批状态" varchar(20) NOT NULL DEFAULT '待审批',
    "审批意见" text,
    "审批人编号" integer REFERENCES "人员"("编号"),
    "审批时间" timestamp without time zone,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 4. 医共体适宜技术推广
CREATE TABLE IF NOT EXISTS "医共体适宜技术推广" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "技术名称" varchar(200) NOT NULL,
    "牵头科室编号" integer REFERENCES "部门"("编号"),
    "牵头专家编号" integer REFERENCES "人员"("编号"),
    "受援基层单位" varchar(200) NOT NULL,
    "推广形式" varchar(50) NOT NULL DEFAULT '现场培训',
    "推广日期" date NOT NULL,
    "培训场次" integer NOT NULL DEFAULT 1,
    "受益医务人员数" integer NOT NULL DEFAULT 0,
    "受益患者人次" integer NOT NULL DEFAULT 0,
    "讲义及签到材料路径" text,
    "推广成效说明" text,
    "记录人编号" integer REFERENCES "人员"("编号"),
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "ix_适宜技术推广_单位日期" ON "医共体适宜技术推广" ("受援基层单位", "推广日期" DESC);

-- 5. 科普成果与临床案例库
CREATE TABLE IF NOT EXISTS "科普成果与临床案例库" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "分类" varchar(30) NOT NULL,
    "形式类型" varchar(50) NOT NULL,
    "成果名称" varchar(300) NOT NULL,
    "第一作者编号" integer NOT NULL REFERENCES "人员"("编号"),
    "第一作者姓名" varchar(50),
    "所属科室编号" integer REFERENCES "部门"("编号"),
    "合作作者" jsonb NOT NULL DEFAULT '[]'::jsonb,
    "完成日期" date NOT NULL,
    "发布载体与平台" varchar(200),
    "受众传播量与成效" integer DEFAULT 0,
    "成果摘要" text,
    "附件路径" text,
    "审核状态" varchar(20) NOT NULL DEFAULT '已入库',
    "审核意见" text,
    "审核人编号" integer REFERENCES "人员"("编号"),
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "ix_科普案例_分类作者" ON "科普成果与临床案例库" ("分类", "第一作者编号", "完成日期" DESC);

-- 6. 职称晋升资格审查记录
CREATE TABLE IF NOT EXISTS "职称晋升资格审查记录" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "人员编号" integer NOT NULL REFERENCES "人员"("编号"),
    "工号" varchar(50),
    "姓名" varchar(50),
    "现专业技术职称" varchar(50),
    "现职称任职日期" date,
    "拟晋升职称" varchar(50) NOT NULL,
    "任职以来课题数" integer NOT NULL DEFAULT 0,
    "第一通讯论文数" integer NOT NULL DEFAULT 0,
    "剔除预警期刊论文数" integer NOT NULL DEFAULT 0,
    "科普与案例数" integer NOT NULL DEFAULT 0,
    "进修满6个月符合" boolean NOT NULL DEFAULT false,
    "近5年继教达标符合" boolean NOT NULL DEFAULT false,
    "业绩详情快照" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "防伪码" varchar(64) NOT NULL UNIQUE,
    "生成人编号" integer REFERENCES "人员"("编号"),
    "生成时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "ix_职称审查_人员" ON "职称晋升资格审查记录" ("人员编号", "生成时间" DESC);

-- 7. 医共体合作单位与人员进修帮扶
CREATE TABLE IF NOT EXISTS "医共体合作单位" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "单位名称" varchar(200) NOT NULL UNIQUE,
    "单位类型" varchar(50) NOT NULL DEFAULT '乡镇卫生院',
    "行政区划" varchar(100),
    "床位数" integer DEFAULT 0,
    "卫技人员数" integer DEFAULT 0,
    "对接联系人" varchar(50),
    "联系电话" varchar(50),
    "合作协议签署日期" date,
    "协议有效期至" date,
    "合作状态" varchar(20) NOT NULL DEFAULT '正常合作',
    "备注" text,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "医共体人员进修与帮扶记录" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "业务类型" varchar(30) NOT NULL DEFAULT '基层来院进修',
    "合作单位编号" bigint REFERENCES "医共体合作单位"("编号"),
    "人员姓名" varchar(50) NOT NULL,
    "人员职称" varchar(50),
    "专业学科" varchar(50),
    "开始日期" date NOT NULL,
    "结束日期" date NOT NULL,
    "带教导师编号" integer REFERENCES "人员"("编号"),
    "考核鉴定结果" varchar(20) DEFAULT '合格',
    "主要帮扶与学习成效" text,
    "附件路径" text,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 初始化部分默认医共体合作单位示范数据
INSERT INTO "医共体合作单位" ("单位名称", "单位类型", "行政区划", "床位数", "卫技人员数", "对接联系人", "联系电话", "合作状态")
VALUES 
    ('县城关镇第一卫生院', '乡镇卫生院', '城关片区', 80, 45, '刘院长', '13800000001', '正常合作'),
    ('县城北社区卫生服务中心', '社区卫生服务中心', '北区', 40, 28, '王主任', '13800000002', '正常合作'),
    ('县柳林中心卫生院', '乡镇卫生院', '柳林镇', 120, 68, '张院长', '13800000003', '正常合作')
ON CONFLICT ("单位名称") DO NOTHING;

-- 8. 菜单权限节点注册
INSERT INTO "权限" ("编号", "上级编号", "名称", "路径", "类型", "图标", "备注")
VALUES 
    (222, 1, '医疗新技术与适宜技术', '科研办公/医疗新技术与适宜技术.html', true, '', '新技术申报、医务科教联合准入、应用例数随访、期满转常规评奖及医共体适宜技术推广'),
    (223, 5, '科普与案例成果库', '成果管理/科普与案例成果库.html', true, '', '医学科普作品、临床典型案例库、护理小发明/实用新型转化'),
    (224, 1, '医共体科教协同', '科研办公/医共体科教协同.html', true, '', '医共体分院与乡镇卫生院科教协同、进修接收、下乡指导与联合课题')
ON CONFLICT ("编号") DO UPDATE
SET "上级编号" = EXCLUDED."上级编号",
    "名称" = EXCLUDED."名称",
    "路径" = EXCLUDED."路径",
    "备注" = EXCLUDED."备注";

-- 授权权限节点给系统管理员、科研管理员、科技办、科室负责人、科研人员
INSERT INTO "角色权限" ("角色编号", "权限编号")
SELECT r."编号", p."编号"
FROM "角色" r
CROSS JOIN "权限" p
WHERE r."编号" IN (1, 3, 4, 5, 15, 1031, 1032, 1033)
  AND p."编号" IN (222, 223, 224)
ON CONFLICT DO NOTHING;

UPDATE "系统迁移版本"
SET "版本" = 116,
    "脚本" = '116_p1_p2_medical_advancement_and_community.sql',
    "检查摘要" = '新增医疗新技术新项目、医共体适宜技术推广、科普案例库、职称资格核验与医共体协同',
    "应用时间" = CURRENT_TIMESTAMP
WHERE "编号" = 1;

COMMIT;
